/**
 * ============================================================================
 * AUDIT REGRESSIONS — A SCHOLAR'S OWN DRAWING, EVERYWHERE IT IS SHOWN
 * ============================================================================
 * Pixel Studio added two seams that the Phase 8 suite could not see, because it
 * tested the Studio's own preview and the resolver separately, never the
 * surface a scholar actually looks at:
 *
 *   1. The Customizer and the Studio Hub preview resolve a configuration against
 *      the **built-in** catalogue only, so an equipped creation degraded to the
 *      base figure there while the dashboard drew the drawing. The customizer's
 *      own documentation says the preview "cannot disagree with what a scholar
 *      gets after saving".
 *   2. The signed-in scholar's creation list is cached in module scope and was
 *      never invalidated, so a creation saved and equipped in the same session
 *      could be missing from the dashboard's catalogue for up to thirty seconds
 *      — long enough for a scholar to see their drawing replaced by the built-in
 *      companion.
 *
 * Both are asserted from the rendered surface: the preview's framebuffer for the
 * first, the number of catalogue reads for the second.
 */

import { cleanup, render, act, fireEvent } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import type { ReactNode } from "react";
import { createRecordingContext } from "@/__tests__/pixel-display/support/recording-renderer";
import { emptyFrame, type PixelCreation } from "@/lib/pixel-display/content/asset";

const recording = createRecordingContext();

let lastLevelUp: { runId: number; newLevel: number; didRankUp?: boolean } | null =
  null;

vi.mock("@/app/components/LevelUpProvider", () => ({
  useLevelUp: () => ({ lastLevelUp }),
}));

let user: unknown = null;
vi.mock("@/app/components/AuthProvider", () => ({
  useAuth: () => ({ user, refreshStats: async () => {} }),
}));

declare global {
  // eslint-disable-next-line no-var
  var __pixelDashboard: {
    handle: { display: { snapshot(): number[] } };
    runtime: { tick(): void };
  } | null;
}

/**
 * The shared recording double covers the display renderer; the studio's editor
 * canvas also clears and fills, so this wraps it with the two calls those
 * surfaces make.
 */
function canvasContextDouble(): CanvasRenderingContext2D {
  const base = recording.context as unknown as Record<string, unknown>;
  const double: Record<string, unknown> = {
    imageSmoothingEnabled: false,
    globalAlpha: 1,
    fillStyle: "#000000",
    clearRect: () => {},
    fillRect: (x: number, y: number, width: number, height: number) =>
      (base.fillRect as (...args: number[]) => void).call(
        double,
        x,
        y,
        width,
        height,
      ),
  };
  return double as unknown as CanvasRenderingContext2D;
}

class FakeResizeObserver {
  observe() {}
  unobserve() {}
  disconnect() {}
}

/** A creation whose drawing is unmistakable: one solid red block, top-left. */
function creationDocument(id = "user:audit-star"): PixelCreation {
  const grid = 48;
  const rows = emptyFrame(grid).rows.map((row, y) =>
    y < 12 ? `${"0".repeat(12)}${row.slice(12)}` : row,
  );
  return {
    version: 1,
    id,
    name: "Audit star",
    grid,
    palette: ["#ff0000"],
    frames: [{ rows, durationMs: 240 }],
    playback: "loop",
  };
}

const STORED_CREATION = {
  id: "cuid-1",
  slug: "audit-star",
  name: "Audit star",
  grid: 48,
  data: creationDocument(),
};

let listReads = 0;
let testOwner = 1200;
let stored: unknown[] = [];

function stubFetch() {
  listReads = 0;
  globalThis.fetch = (async (input: RequestInfo | URL, init?: RequestInit) => {
    const url = String(input);
    if (url.includes("/api/pixel-creations")) {
      if (init?.method === "POST") {
        return {
          ok: true,
          status: 200,
          json: async () => ({ creation: STORED_CREATION }),
        } as unknown as Response;
      }
      listReads += 1;
      return {
        ok: true,
        status: 200,
        json: async () => ({ creations: stored }),
      } as unknown as Response;
    }
    return { ok: false, status: 404, json: async () => ({}) } as unknown as Response;
  }) as unknown as typeof fetch;
}

beforeEach(async () => {
  recording.reset();
  lastLevelUp = null;
  stored = [STORED_CREATION];
  stubFetch();
  globalThis.__pixelDashboard = null;
  user = { id: ++testOwner, characterConfig: CONFIG };
  listReads = 0;
  vi.stubEnv("NODE_ENV", "development");
  window.matchMedia = ((query: string) => ({
    matches: false,
    media: query,
    onchange: null,
    addEventListener: () => {},
    removeEventListener: () => {},
    addListener: () => {},
    removeListener: () => {},
    dispatchEvent: () => false,
  })) as unknown as typeof window.matchMedia;
  (globalThis as Record<string, unknown>).ResizeObserver = FakeResizeObserver;
  HTMLCanvasElement.prototype.getContext = (() =>
    canvasContextDouble()) as unknown as HTMLCanvasElement["getContext"];
  HTMLElement.prototype.getBoundingClientRect = function () {
    return {
      width: 180, height: 180, top: 0, left: 0, right: 180, bottom: 180, x: 0, y: 0,
      toJSON: () => ({}),
    } as DOMRect;
  };
  const { invalidateScholarCreations } = await import(
    "@/app/dashboard/pixel-companion-adapter"
  );
  invalidateScholarCreations();
});

afterEach(() => {
  cleanup();
  vi.unstubAllEnvs();
});

const { PixelCustomizer } = await import(
  "@/app/locker/components/identity/PixelCustomizer"
);
const { PixelCompanionCard } = await import(
  "@/app/dashboard/components/PixelCompanionCard"
);
const { invalidateScholarCreations } = await import(
  "@/app/dashboard/pixel-companion-adapter"
);

const CONFIG = {
  outfit: "user:audit-star",
  pedestal: "pedestal_cyber",
  aura: "none",
  relic: "none",
  density: "detailed",
} as never;

function redCells(): number {
  const preview = (window as unknown as { __pixelDisplays?: Map<string, { runtime: { tick(): void }; display: { snapshot(): number[] } }> }).__pixelDisplays?.get("Customizer preview");
  if (preview) { preview.runtime.tick(); return preview.display.snapshot().filter(color => (color >>> 8) === 0xff0000).length; }
  const probe = globalThis.__pixelDashboard;
  if (!probe) return -1;
  probe.runtime.tick();
  const snapshot = probe.handle.display.snapshot();
  return snapshot.filter((color) => (color >>> 8) === 0xff0000).length;
}

describe("the customizer preview of an equipped creation", () => {
  it("shows the scholar's drawing, not the built-in companion", async () => {
    render(
      (
        <PixelCustomizer
          characterConfig={CONFIG}
          savedConfig={CONFIG}
          user={{ hunterRank: "RANK E", level: 1 }}
          onChange={() => {}}
          onReset={() => {}}
          onSave={() => {}}
          onBack={() => {}}
        />
      ) as ReactNode as never,
    );

    await act(async () => {
      await Promise.resolve();
    });
    // The drawing arrives after the catalogue read resolves, so poll for it
    // rather than sampling once.
    await vi.waitFor(() => expect(redCells()).toBeGreaterThan(0));
  });
});

describe("the dashboard catalogue after a save", () => {
  it("selects future paint directly through hex, spectrum and recent colors without editing history", async () => {
    const { PixelStudio } = await import("@/app/locker/components/studio/PixelStudio");
    const view = render(<PixelStudio characterConfig={CONFIG} onEquip={() => {}} onBack={() => {}} />);
    const hex = view.getByRole("textbox", { name: "Paint color hex" });
    fireEvent.change(hex, { target: { value: "#F04A29" } }); fireEvent.blur(hex);
    expect(view.getByRole("button", { name: "Recent color #f04a29" }).getAttribute('aria-pressed')).toBe('true');
    expect((view.getByRole("button", { name: "Undo" }) as HTMLButtonElement).disabled).toBe(true);
    expect(view.queryByRole("button", { name: "Use color" })).toBeNull();
    expect(view.queryByRole("button", { name: "Replace selected" })).toBeNull();
    fireEvent.change(view.getByLabelText("Paint color spectrum"), { target: { value: '#2288dd' } });
    expect(view.getByRole("button", { name: "Recent color #2288dd" }).getAttribute('aria-pressed')).toBe('true');
    fireEvent.click(view.getByRole("button", { name: "Recent color #f04a29" }));
    expect((view.getByRole("textbox", { name: "Paint color hex" }) as HTMLInputElement).value).toBe('#f04a29');
    expect((view.getByRole("button", { name: "Undo" }) as HTMLButtonElement).disabled).toBe(true);
    fireEvent.click(view.getByRole("checkbox", { name: "Show border" }));
    const border = view.getByRole("textbox", { name: "Border color hex" });
    fireEvent.change(border, { target: { value: "#FF7700" } }); fireEvent.blur(border);
    expect(view.container.querySelector('[data-display-border="#ff7700"]')).toBeTruthy();
    fireEvent.click(view.getByRole("button", { name: "Undo" }));
    expect(view.container.querySelector('[data-display-border="#ff7700"]')).toBeNull();
  });
  it("applies border and spacing with Save while leaving the equipped artwork selection alone", async () => {
    const { PixelStudio } = await import("@/app/locker/components/studio/PixelStudio");
    const onEquip = vi.fn();
    const view = render(<PixelStudio characterConfig={CONFIG} onEquip={onEquip} onBack={() => {}} />);
    fireEvent.click(view.getByRole("checkbox", { name: "Show border" }));
    fireEvent.change(view.getByRole("slider", { name: "Pixel spacing" }), { target: { value: "20" } });
    await act(async () => { fireEvent.click(view.getByRole("button", { name: /^Save$/ })); await Promise.resolve(); });
    expect(onEquip).toHaveBeenCalledWith({ displayBorder: '#5ac9d1', pixelGap: 0.2 });
    expect(onEquip.mock.calls[0][0]).not.toHaveProperty('outfit');
  });
  it("lets a duration be typed digit by digit and undoes the committed value as one edit", async () => {
    const { PixelStudio } = await import("@/app/locker/components/studio/PixelStudio");
    const view = render(<PixelStudio characterConfig={CONFIG} onEquip={() => {}} onBack={() => {}} />);
    const input = view.getByRole("spinbutton") as HTMLInputElement;
    fireEvent.focus(input);
    fireEvent.change(input, { target: { value: "1" } });
    for (const digit of "200") fireEvent.change(input, { target: { value: input.value + digit } });
    expect(input.value).toBe("1200");
    fireEvent.blur(input);
    expect(view.getByRole("button", { name: "Frame 1, 1200 milliseconds" })).toBeTruthy();
    fireEvent.click(view.getByRole("button", { name: "Undo" }));
    expect((view.getByRole("spinbutton") as HTMLInputElement).value).toBe("240");
  });
  it("keeps a legacy blank draft editable without resolving it as equipped artwork", async () => {
    stored = [{ ...STORED_CREATION, data: { ...creationDocument(), frames: [emptyFrame(48)] } }];
    const { usePixelCreations } = await import("@/lib/pixel-creations-client");
    function LibraryProbe() {
      const library = usePixelCreations(testOwner);
      return <output data-testid="library">{JSON.stringify({ loaded: library.loaded, documents: library.creations.length, equippedAssets: library.assets.length })}</output>;
    }
    const view = render(<LibraryProbe />);
    await vi.waitFor(() => expect(JSON.parse(view.getByTestId("library").textContent!)).toEqual({ loaded: true, documents: 1, equippedAssets: 0 }));
  });
  it("reads the catalogue again, so a new drawing can be drawn", async () => {
    // An empty list fills the cache, exactly as opening the app does.
    stored = [];
    const first = render(<PixelCompanionCard size={110} /> as ReactNode as never);
    await vi.waitFor(() => expect(listReads).toBe(1));
    first.unmount();

    // The scholar's drawing is saved. The studio owns that write.
    stored = [STORED_CREATION];
    const { PixelStudio } = await import("@/app/locker/components/studio/PixelStudio");
    const studio = render(
      (
        <PixelStudio
          characterConfig={CONFIG}
          onEquip={() => {}}
          onBack={() => {}}
        />
      ) as ReactNode as never,
    );
    const save = studio.getByRole("button", { name: /^Save$/ });
    expect(save).not.toBeNull();
    await act(async () => {
      (save as HTMLButtonElement).click();
      await Promise.resolve();
    });
    studio.unmount();

    // The scholar is now wearing it, and opens the dashboard again. Only reads
    // made from here on are counted, so a read by the studio itself cannot
    // satisfy the assertion.
    listReads = 0;
    user = {
      id: testOwner,
      characterConfig: { outfit: "user:audit-star", pedestal: "pedestal_cyber" },
      hunterRank: "RANK E",
      level: 1,
    };
    const second = render(<PixelCompanionCard size={110} /> as ReactNode as never);
    // Save invalidation refreshes mounted subscribers; remount reuses that fresh list.
    expect(listReads).toBe(0);
    await vi.waitFor(() => expect(redCells()).toBeGreaterThan(0));
    second.unmount();
  });
});

describe("a level-up on the production card", () => {
  it("moves the drawn companion into its celebrating posture", async () => {
    user = { id: testOwner, characterConfig: { outfit: "sylf", pedestal: "pedestal_cyber" } };
    const { SYLF_PALETTE } = await import("@/lib/pixel-display/content/palette");
    const view = render(<PixelCompanionCard size={110} /> as ReactNode as never);
    await vi.waitFor(() => expect(globalThis.__pixelDashboard).toBeTruthy());

    const blushCells = () => {
      const probe = globalThis.__pixelDashboard!;
      probe.runtime.tick();
      return probe.handle.display
        .snapshot()
        .filter((color) => color === SYLF_PALETTE.blush).length;
    };
    expect(blushCells()).toBe(0);

    // The application reports a level-up; the card reads it from its owner.
    await act(async () => {
      lastLevelUp = { runId: 1, newLevel: 12 };
      view.rerender(<PixelCompanionCard size={110} /> as ReactNode as never);
    });

    const card = view.container.querySelector("[data-companion='pixel-display']");
    expect(card?.getAttribute("data-state")).toBe("CELEBRATING");
    // …and the picture agrees with the attribute, which is what was broken.
    await vi.waitFor(() => expect(blushCells()).toBeGreaterThan(0));
    view.unmount();
  });
});

/** @vitest-environment jsdom */
import React from "react";
import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import { render, screen, fireEvent, act } from "@testing-library/react";
import { FocusPartyRoom } from "@/app/social/components/focus-party/FocusPartyRoom";
import * as FocusPartyContextModule from "@/app/social/components/focus-party/FocusPartyContext";
import * as FocusBackgroundClientModule from "@/lib/focus-background-client";
import * as FocusBackgroundPreferenceModule from "@/lib/focus-background-preference";
import { resolvePartySafeTimerPosition } from "@/app/social/components/focus-party/FocusPartyTimerLayoutRouter";

// Mock the explicit target-owner Pixel presenter
vi.mock("@/app/components/companion/TargetPixelCompanion", () => ({
  TargetPixelCompanion: ({ companion, size }: any) => (
    <div data-testid={`pixel-companion-${companion?.ownerId ?? "unavailable"}`} data-owner={companion?.ownerId}>
      Pixel companion ({companion?.ownerId ?? "unavailable"})
    </div>
  ),
}));

// Mock AuthProvider
let mockUser: any = { id: 1, username: "ali", name: "Ali", hunterRank: "S", level: 25 };
vi.mock("@/app/components/AuthProvider", () => ({
  useAuth: () => ({
    user: mockUser,
    isLoading: false,
  }),
}));

// Mock next/navigation
vi.mock("next/navigation", () => ({
  useRouter: () => ({
    push: vi.fn(),
    replace: vi.fn(),
    back: vi.fn(),
  }),
  useSearchParams: () => new URLSearchParams(),
  usePathname: () => "/focus-party/10/focus",
}));

describe("Focus Party & Solo Focus Background System Unification Rigorous Verification", () => {
  const mockCatalog: FocusBackgroundClientModule.FocusBackgroundCatalog = {
    categories: [
      FocusBackgroundClientModule.SYNTHETIC_CLASSIC_CATEGORY,
      {
        id: 2,
        slug: "anime",
        name: "Anime Framing",
        layoutKey: "anime",
        sortOrder: 1,
        isActive: true,
        backgrounds: [
          {
            id: 101,
            categoryId: 2,
            name: "Neon Cybercity",
            storagePath: "official/neon.webp",
            width: 1920,
            height: 1080,
            aspectRatio: 1.7778,
            focalX: 0.75,
            focalY: 0.5,
            timerPosition: "left",
            sortOrder: 0,
            isActive: true,
            publicUrl: "https://mock.storage/neon.webp",
          },
        ],
      },
      {
        id: 3,
        slug: "landscapes",
        name: "Landscapes",
        layoutKey: "landscape",
        sortOrder: 2,
        isActive: true,
        backgrounds: [
          {
            id: 102,
            categoryId: 3,
            name: "Misty Mountains",
            storagePath: "official/mountains.webp",
            width: 1920,
            height: 1080,
            aspectRatio: 1.7778,
            focalX: 0.5,
            focalY: 0.5,
            timerPosition: "center",
            sortOrder: 0,
            isActive: true,
            publicUrl: "https://mock.storage/mountains.webp",
          },
        ],
      },
      {
        id: 4,
        slug: "fantasy",
        name: "Fantasy & Sanctum",
        layoutKey: "fantasy",
        sortOrder: 3,
        isActive: true,
        backgrounds: [
          {
            id: 103,
            categoryId: 4,
            name: "Grand Astrolabe",
            storagePath: "official/astrolabe.webp",
            width: 1920,
            height: 1080,
            aspectRatio: 1.7778,
            focalX: 0.25,
            focalY: 0.5,
            timerPosition: "right",
            sortOrder: 0,
            isActive: true,
            publicUrl: "https://mock.storage/astrolabe.webp",
          },
        ],
      },
    ],
  };

  const mockCustomBg = {
    id: 301,
    userId: 1,
    name: "My Private Study",
    width: 1920,
    height: 1080,
    aspectRatio: 1.7778,
    focalX: 0.5,
    focalY: 0.5,
    timerPosition: "center" as const,
    signedUrl: "https://mock.storage/user-1/private.webp?token=initial",
    signedUrlExpiresAt: new Date(Date.now() + 3600 * 1000).toISOString(),
    fileSize: 102400,
    mimeType: "image/webp",
    createdAt: new Date().toISOString(),
  };

  const mockSessionData = {
    id: 100,
    startedAt: new Date().toISOString(),
    collectiveSeconds: 1200,
    members: [
      {
        userId: 1,
        timerState: "FOCUSING" as const,
        accumulatedSeconds: 600,
        currentStartedAt: new Date().toISOString(),
        liveSeconds: 600,
        isFocusing: true,
      },
      {
        userId: 2,
        timerState: "FOCUSING" as const,
        accumulatedSeconds: 600,
        currentStartedAt: new Date().toISOString(),
        liveSeconds: 600,
        isFocusing: true,
      },
    ],
  };

  const mockPartyData = {
    party: {
      id: 10,
      name: "Solitary Hunters",
      leaderId: 1,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      disbandedAt: null,
      isCurrentUserLeader: true,
      memberCount: 2,
    },
    members: [
      {
        userId: 1,
        name: "Ali",
        username: "ali",
        hunterRank: "S",
        avatarUrl: null,
        characterConfig: null,
        joinedAt: new Date().toISOString(),
        isLeader: true,
      },
      {
        userId: 2,
        name: "Bob",
        username: "bob",
        hunterRank: "A",
        avatarUrl: null,
        characterConfig: null,
        joinedAt: new Date().toISOString(),
        isLeader: false,
      },
    ],
    activeSession: mockSessionData,
  };

  const setupRoom = (overrides = {}) => {
    vi.spyOn(FocusPartyContextModule, "useFocusParty").mockReturnValue({
      partySummary: mockPartyData.party,
      party: mockPartyData,
      session: mockSessionData,
      timerViews: {
        1: mockSessionData.members[0],
        2: mockSessionData.members[1],
      },
      collectiveSeconds: 1200,
      connectionState: "connected",
      pendingInvites: [],
      viewMode: "room",
      setViewMode: vi.fn(),
      isLoading: false,
      isActionLoading: false,
      error: null,
      hasActiveParty: true,
      isLeader: true,
      isInFocus: true,
      myParticipant: mockSessionData.members[0],
      myTimerView: mockSessionData.members[0],
      myTimerState: "FOCUSING",
      myLiveSeconds: 600,
      refresh: vi.fn(),
      createParty: vi.fn(),
      joinParty: vi.fn(),
      leaveParty: vi.fn(),
      kickMember: vi.fn(),
      inviteFriend: vi.fn(),
      respondToInvite: vi.fn(),
      enterFocus: vi.fn(),
      startTimer: vi.fn(),
      pauseTimer: vi.fn(),
      resumeTimer: vi.fn(),
      leaveFocus: vi.fn(),
      clearError: vi.fn(),
      ...overrides,
    });
  };

  beforeEach(() => {
    vi.clearAllMocks();
    localStorage.clear();
    mockUser = { id: 1, username: "ali", name: "Ali", hunterRank: "S", level: 25 };

    vi.spyOn(FocusBackgroundClientModule, "fetchFocusBackgroundCatalog").mockResolvedValue(mockCatalog);
    vi.spyOn(FocusBackgroundClientModule, "preloadFocusImage").mockResolvedValue(true);
    vi.spyOn(FocusBackgroundPreferenceModule, "fetchServerPreference").mockResolvedValue({
      initialized: true,
      version: 1,
      source: "classic",
      categorySlug: "classic-sylf",
      backgroundId: null,
      isClassic: true,
      customBackground: null,
    });
    vi.spyOn(FocusBackgroundPreferenceModule.focusPreferenceQueue, "enqueue").mockResolvedValue({
      success: true,
      data: {
        initialized: true,
        version: 2,
        source: "classic",
        categorySlug: "classic-sylf",
        backgroundId: null,
        isClassic: true,
        customBackground: null,
      },
    });

    global.fetch = vi.fn().mockImplementation((url: string) => {
      if (url.includes("/api/user/focus-backgrounds")) {
        return Promise.resolve({
          ok: true,
          json: () => Promise.resolve({ backgrounds: [mockCustomBg] }),
        });
      }
      return Promise.resolve({
        ok: true,
        json: () => Promise.resolve({}),
      });
    }) as any;
  });

  afterEach(() => {
    localStorage.clear();
  });

  // ── Verification 1 & 2: Bi-directional Shared Preference Sync ─────────────
  it("1. Solo selects Anime -> Party opens with Anime environment", async () => {
    // Simulate user selecting Anime in Solo Focus (stored in localStorage & server)
    FocusBackgroundPreferenceModule.saveStoredPreference({
      source: "official",
      categorySlug: "anime",
      backgroundId: 101,
    });
    vi.spyOn(FocusBackgroundPreferenceModule, "fetchServerPreference").mockResolvedValueOnce({
      initialized: true,
      version: 2,
      source: "official",
      categorySlug: "anime",
      backgroundId: 101,
      isClassic: false,
      customBackground: null,
    });

    setupRoom();
    await act(async () => {
      render(<FocusPartyRoom />);
    });

    expect(screen.getByTestId("focus-bg-image")).toBeInTheDocument();
    expect(screen.getByTestId("party-timer-dock-anime")).toBeInTheDocument();
    expect(screen.getByText("Neon Cybercity")).toBeInTheDocument();
  });

  it("2. Party selects Fantasy -> Solo now has Fantasy preference stored", async () => {
    setupRoom();
    await act(async () => {
      render(<FocusPartyRoom />);
    });

    // User clicks environment button in party room
    fireEvent.click(screen.getByTestId("env-selector-btn"));

    // Select Fantasy category and Grand Astrolabe
    fireEvent.click(screen.getByRole("tab", { name: /Fantasy/i }));
    await act(async () => {
      fireEvent.click(screen.getByText("Grand Astrolabe"));
    });

    // Verifies shared preference queue enqueued update
    expect(FocusBackgroundPreferenceModule.focusPreferenceQueue.enqueue).toHaveBeenCalledWith({
      source: "official",
      backgroundId: 103,
    });

    // Verifies local storage holds Fantasy preference (read by Solo Focus)
    const stored = FocusBackgroundPreferenceModule.loadStoredPreference();
    expect(stored.source).toBe("official");
    expect(stored.categorySlug).toBe("fantasy");
    expect(stored.backgroundId).toBe(103);
  });

  // ── Verification 3: Custom Background Shared Selection ─────────────────────
  it("3. Party selects custom background -> stored preference reflects custom", async () => {
    setupRoom();
    await act(async () => {
      render(<FocusPartyRoom />);
    });

    fireEvent.click(screen.getByTestId("env-selector-btn"));
    fireEvent.click(screen.getByRole("tab", { name: /My Backgrounds/i }));

    await act(async () => {
      fireEvent.click(screen.getByText("My Private Study"));
    });

    expect(FocusBackgroundPreferenceModule.focusPreferenceQueue.enqueue).toHaveBeenCalledWith({
