              {quests.length === 0 ? (
                <div className={styles.emptyContainer}>
                  <div className={styles.emptyIconCircle}>
                    <QuestEmblemIcon size={18} />
                  </div>
                  <p className={styles.emptyText}>
                    No quests assigned for today.
