                            </button>
                          )}
                          {quest.status === "PENDING" && !isCurrentTarget && (
                            <button
                              onClick={() =>
                                router.push(
                                  `/focus?questId=${quest.id}&subjectName=${encodeURIComponent(
                                    quest.title
                                  )}`
                                )
                              }
                              className={styles.btnStart}
                            >
                              <Play size={11} fill="currentColor" />
