              <div className="w-full mt-4 p-3 rounded-xl bg-[var(--page)] border border-[var(--subtle-line)] flex flex-col gap-1 text-left">
                <span className="text-[10px] font-bold font-['Rajdhani'] text-[var(--muted)] uppercase">
