"use client";

// ============================================================================
// FocusPartyRoom — Dedicated Focus Room (Unified Background & Timer Architecture)
// ============================================================================
// Unifies the Focus Party Focus Room with the authoritative Solo Focus
// Background & Preference system:
//   1. Shared Background Engine: FocusBackgroundRenderer renders the active
//      environment wallpaper (Classic gradient, official image with focal crop,
//      or signed custom background).
//   2. Personal Viewers: Each member client renders its own saved preference.
//      Leader preference is never forced; party realtime state is unaffected.
//   3. Reserved Member Stage: FocusPartyMemberStage displays the 4 member cards
//      and vacant slots 1:1, stationary and unaffected by background focal point.
//   4. Party-Safe Timer Router: FocusPartyTimerLayoutRouter renders Classic,
//      Anime, Landscape, or Fantasy timer styling strictly in the lower dock,
//      guaranteeing zero obstruction of the member cards.
//   5. Shared Picker: Directly reuses FocusBackgroundPicker to view/select
//      Classic, Anime, Landscape, Fantasy, and My Backgrounds.
// ============================================================================

import React, { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import {
  ArrowLeft,
  LogOut,
  Loader2,
  AlertCircle,
  X,
  CheckCircle2,
  Compass,
} from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import { useFocusParty } from "./FocusPartyContext";
import { formatFocusTime } from "./focus-party-utils";
import { useAuth } from "@/app/components/AuthProvider";
import type { MemberTimerView, FocusPartyMemberView } from "@/lib/focus-party-types";
import { useFocusBackground } from "@/app/focus/hooks/useFocusBackground";
import { FocusBackgroundRenderer } from "@/app/focus/components/FocusBackgroundRenderer";
import FocusBackgroundPicker from "@/app/focus/components/FocusBackgroundPicker";
import {
  FocusPartyMemberStage,
  FocusPartyStageParticipant,
} from "./FocusPartyMemberStage";
import { FocusPartyTimerLayoutRouter } from "./FocusPartyTimerLayoutRouter";

export function FocusPartyRoom() {
  let router: any = null;
  try {
    router = useRouter();
  } catch {
    router = { push: () => {}, replace: () => {}, back: () => {} };
  }

  const { user } = useAuth();
  const currentUserId = user?.id ?? null;

  const {
    party,
    session,
    timerViews,
    collectiveSeconds,
    myTimerState,
    myLiveSeconds,
    startTimer,
    pauseTimer,
    resumeTimer,
    leaveFocus,
    setViewMode,
    isActionLoading,
    error,
    clearError,
    isLoading,
    connectionState,
  } = useFocusParty();

  // ─── Shared Focus Background Engine ─────────────────────────────────────────
  const focusBg = useFocusBackground();

  const [sessionEndingMessage, setSessionEndingMessage] = useState<string | null>(null);

  // ─── 1. Session Ending & Navigation Safety Watcher ───────────────────────────
  useEffect(() => {
    // If party disbanded or session ended while in room
    if (!isLoading && party && !session && !sessionEndingMessage) {
      setSessionEndingMessage("Study session concluded. Returning to lobby...");
      const t = setTimeout(() => {
        setViewMode("lobby");
        if (router?.push) {
          router.push("/social?tab=party");
        }
      }, 1500);
      return () => clearTimeout(t);
    }
  }, [isLoading, party, session, sessionEndingMessage, router, setViewMode]);

  if (!party || !session) {
    if (sessionEndingMessage) {
      return (
        <div className="min-h-screen w-full flex flex-col items-center justify-center p-6 bg-bg-void dark:bg-bg-abyss text-center font-['Rajdhani']">
          <div className="w-12 h-12 rounded-2xl bg-emerald-500/10 border border-emerald-500/30 flex items-center justify-center text-emerald-400 mb-4 animate-pulse">
            <CheckCircle2 className="w-6 h-6" />
          </div>
          <h3 className="text-xl font-bold uppercase tracking-wider text-text-primary mb-1">
            Session Ended
          </h3>
          <p className="text-sm text-text-muted font-mono">{sessionEndingMessage}</p>
        </div>
      );
    }
    return (
      <div
        data-testid="focus-room-loading"
        className="min-h-[400px] w-full flex flex-col items-center justify-center p-8 text-center font-['Rajdhani']"
      >
        <Loader2 className="w-8 h-8 text-accent-primary-light animate-spin mb-3" />
        <p className="text-xs uppercase tracking-widest text-text-muted font-bold">
          Connecting to Study Room...
        </p>
      </div>
    );
  }

  const partyMembers = party.members || [];
  const memberMap = new Map<number, FocusPartyMemberView>(
    partyMembers.map((m) => [m.userId, m])
  );

  const sessionMembers = session.members || [];
  // Actively participating in current session
  const activeParticipants = sessionMembers.filter(
    (p: MemberTimerView) => p.timerState !== "LEFT"
  );

  // ─── 2. Timer Action Handler (Single Primary Action) ────────────────────────
  const handleTimerAction = async () => {
    if (myTimerState === "NOT_STARTED") {
      await startTimer();
    } else if (myTimerState === "FOCUSING") {
      await pauseTimer();
    } else if (myTimerState === "PAUSED") {
      await resumeTimer();
    }
  };

  // Back to Lobby: Keeps session active, user remains in study room
  const handleBackToLobby = () => {
    setViewMode("lobby");
    if (router?.push) {
      router.push("/social?tab=party");
    }
  };

  // Leave Focus: Banks study time and exits session
  const handleConfirmLeaveFocus = async () => {
    const res = await leaveFocus();
    if (res?.success) {
      setViewMode("lobby");
      if (router?.push) {
        router.push("/social?tab=party");
      }
    }
  };

  // ─── 3. Normalized Participants for Presentational Stage ───────────────────
  const normalizedParticipants: FocusPartyStageParticipant[] = activeParticipants.map(
    (p) => {
      const profile = memberMap.get(p.userId);
      const liveSeconds = timerViews[p.userId]?.liveSeconds ?? p.accumulatedSeconds ?? 0;
      const state = timerViews[p.userId]?.timerState ?? p.timerState;
      return {
        userId: p.userId,
        name: profile?.name || profile?.username || `Scholar #${p.userId}`,
        username: profile?.username || `user_${p.userId}`,
        hunterRank: profile?.hunterRank,
        characterConfig: profile?.characterConfig,
        companion: profile?.companion,
        avatarUrl: profile?.avatarUrl,
        timerState: state,
        liveSeconds,
        isCurrentUser: p.userId === currentUserId,
      };
    }
  );

  const activeEnvName = focusBg.isClassic
    ? "Classic Sylf"
    : focusBg.activeBackground?.name || "Environment";

  return (
    <div className="relative min-h-screen w-full flex flex-col justify-between font-['Rajdhani'] select-none overflow-x-hidden isolate">
      {/* ─── 0. Unified Focus Background Wallpaper (z-0) ────────────────── */}
      <FocusBackgroundRenderer
        activeBackground={focusBg.activeBackground}
        isClassic={focusBg.isClassic}
        phase={myTimerState === "PAUSED" ? "short-break" : "focus"}
        layoutKey={focusBg.layoutKey}
        onImageError={focusBg.onImageDeliveryError}
      />

      {/* ─── 1. Lightweight Minimal Header Bar (z-30) ────────────────────── */}
      <header className="w-full px-4 sm:px-6 py-2.5 border-b border-border-subtle bg-white/95 dark:bg-bg-panel/95 backdrop-blur-md relative z-30 flex items-center justify-between min-h-[54px] shadow-sm">
        {/* Left: Quiet Navigation Back to Lobby */}
        <div className="flex items-center z-10">
          <button
            type="button"
            data-testid="back-to-lobby-btn"
            aria-label="Back to Lobby"
            onClick={handleBackToLobby}
            className="flex items-center gap-1.5 py-1.5 px-3 sm:px-3.5 rounded-xl border border-border-subtle dark:border-white/10 hover:border-text-secondary/40 bg-slate-900/5 hover:bg-slate-900/10 dark:bg-white/[0.03] dark:hover:bg-white/[0.08] text-text-muted hover:text-text-primary text-xs font-bold uppercase tracking-wider transition-all active:scale-95 cursor-pointer"
            title="Return to Party Lobby (Timer & session keep running in background)"
          >
            <ArrowLeft className="w-3.5 h-3.5" />
            <span className="hidden sm:inline">Lobby</span>
          </button>
        </div>

        {/* Center: Perfectly Centered Room Title + Solidarity Counter */}
        <div className="absolute left-1/2 -translate-x-1/2 top-1/2 -translate-y-1/2 flex flex-col items-center text-center pointer-events-none max-w-[50%] sm:max-w-[60%]">
          <div className="flex items-center gap-2">
            {connectionState === "connected" && (
              <span className="w-1.5 h-1.5 rounded-full flex-shrink-0 bg-emerald-400 shadow-[0_0_8px_rgba(16,185,129,0.8)] animate-pulse" />
            )}
            <h1 className="text-xs sm:text-sm font-bold tracking-wider text-text-primary uppercase truncate max-w-[140px] sm:max-w-xs">
              {party.party.name}
            </h1>
            <span className="text-text-muted/60 text-xs hidden sm:inline">•</span>
            <span className="text-[11px] font-mono font-bold tracking-widest text-accent-text-light uppercase hidden sm:inline">
              FOCUS ROOM
            </span>
            <span className="sr-only">ACTIVE FOCUS ROOM</span>
          </div>

          <div className="flex items-center gap-2 text-[11px] font-mono text-text-muted mt-0.5">
            <span className="text-text-secondary">{activeParticipants.length} STUDYING</span>
            <span>•</span>
            <div className="flex items-center gap-1">
              <span>Together</span>
              <span
                data-testid="collective-focus-timer"
                className="text-emerald-400 font-bold tracking-wider"
              >
                {formatFocusTime(collectiveSeconds)}
              </span>
            </div>
          </div>
        </div>

        {/* Right: Shared Focus Environment Selector + Leave Focus */}
        <div className="flex items-center gap-2 z-10">
          <button
            type="button"
            data-testid="env-selector-btn"
            aria-label={`Change study environment, current: ${activeEnvName}`}
            onClick={focusBg.openPicker}
            className="flex items-center gap-1.5 py-1.5 px-2.5 sm:px-3 rounded-xl border border-border-subtle dark:border-white/10 hover:border-text-secondary/40 bg-slate-900/5 hover:bg-slate-900/10 dark:bg-white/[0.03] dark:hover:bg-white/[0.08] text-text-secondary hover:text-text-primary text-xs font-bold uppercase tracking-wider transition-all active:scale-95 cursor-pointer shadow-sm"
            title="Change Study Environment"
          >
            <Compass className="w-3.5 h-3.5 text-accent-light" />
            <span className="hidden md:inline">{activeEnvName}</span>
          </button>

          <button
            type="button"
            data-testid="leave-focus-room-btn"
            aria-label="Leave Focus"
            onClick={handleConfirmLeaveFocus}
            disabled={isActionLoading}
            className="flex items-center gap-1.5 py-1.5 px-2.5 sm:px-3 rounded-xl border border-rose-500/20 hover:border-rose-500/40 bg-rose-500/10 hover:bg-rose-500/20 text-rose-300 text-xs font-bold uppercase tracking-wider transition-all active:scale-95 disabled:opacity-50 cursor-pointer"
            title="Bank study time and exit focus session"
          >
            {isActionLoading ? (
              <Loader2 className="w-3.5 h-3.5 animate-spin" />
            ) : (
              <LogOut className="w-3.5 h-3.5" />
            )}
            <span className="hidden sm:inline">Leave Focus</span>
          </button>
        </div>
      </header>

      {/* ─── Error Notification ─────────────────────────────────────────── */}
      <AnimatePresence>
        {(error || focusBg.loadError || focusBg.syncError) && (
          <motion.div
            initial={{ opacity: 0, y: -8 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -8 }}
            className="mx-4 sm:mx-6 my-2 py-2 px-4 rounded-xl border border-rose-500/30 bg-rose-950/50 text-rose-300 text-xs font-mono flex items-center justify-between z-30"
          >
            <div className="flex items-center gap-2">
              <AlertCircle className="w-4 h-4 flex-shrink-0" />
              <span>{error || focusBg.loadError || focusBg.syncError}</span>
            </div>
            <button
              onClick={() => {
                clearError();
                focusBg.clearLoadError();
                focusBg.clearSyncError();
              }}
              className="text-text-muted hover:text-text-primary ml-2 p-1"
            >
              <X className="w-3.5 h-3.5" />
            </button>
          </motion.div>
        )}
      </AnimatePresence>

      {/* ─── 2. Main Stage: Reserved Member Card Zone + Lower Timer Dock ── */}
      <main className="flex-1 w-full max-w-6xl mx-auto px-4 sm:px-6 py-2 flex flex-col justify-between items-center z-10">
        {/* Reserved Member Card Stage: Stationary center/upper viewport */}
        <FocusPartyMemberStage
          participants={normalizedParticipants}
          maxCapacity={4}
        />

        {/* Party-Safe Timer Presentation Router: strictly docked below member cards */}
        <FocusPartyTimerLayoutRouter
          myTimerState={myTimerState}
          myLiveSeconds={myLiveSeconds}
          isActionLoading={isActionLoading}
          onAction={handleTimerAction}
          layoutKey={focusBg.layoutKey}
          background={
            focusBg.activeSource === "custom"
              ? (focusBg.activeCustomBackground as any)
              : focusBg.activeBackground
          }
        />
      </main>

      {/* ─── 3. Shared Focus Background Picker Modal ────────────────────── */}
      <FocusBackgroundPicker
        isOpen={focusBg.isPickerOpen}
        onClose={focusBg.closePicker}
        catalog={focusBg.catalog}
        activeCategory={focusBg.activeCategory}
        activeBackground={focusBg.activeBackground}
        isClassic={focusBg.isClassic}
        isPreloadingImage={focusBg.isPreloadingImage}
        loadError={focusBg.loadError || focusBg.syncError}
        onSelectBackground={focusBg.selectBackground}
        userCustomBackgrounds={focusBg.customBackgrounds}
        activeSource={focusBg.activeSource}
        activeCustomBackground={focusBg.activeCustomBackground}
        onSelectCustomBackground={focusBg.selectCustomBackground}
      />
    </div>
  );
}

/**
 * ============================================================================
 * PIXEL CREATION — WHAT A USER DRAWS
 * ============================================================================
 * The authored format Pixel Studio produces, and the validation that stands
 * between it and the display.
 *
 * WHY THIS IS NOT A `PixelAsset`
 *   A `PixelAsset` is a *developer* description: named planes, anchors, states,
 *   attachments, a reference grid chosen per asset. A user drawing is much
 *   smaller than that — a grid, some colours, some frames — and much more
 *   dangerous: it arrives from a client.
 *
 *   So this is a separate, minimal, **versioned** format with hard bounds, and it
 *   is converted into a `PixelAsset` only after it validates. The conversion is
 *   one-way: a creation can become an asset, and an asset can never become a
 *   creation. That keeps the trusted and untrusted sides apart, which is the
 *   whole point.
 *
 * EVERYTHING HERE TREATS ITS INPUT AS HOSTILE
 *   Bounds are checked before anything is decoded, the decoder is total (it never
 *   throws), and validation fails closed with a reason per problem. Nothing in
 *   this module executes user input, and nothing allocates unboundedly from it.
 *
 * PIXELS ARE STORED AS PALETTE INDICES
 *   A frame is rows of digits, one digit per cell, indexing the creation's own
 *   palette. `.` is never a digit, so transparent is unambiguous and a frame's
 *   rows are exactly as wide as the grid. Indices keep a 48 × 48 × 8-frame
 *   creation under 20 KB of JSON, which is what makes storing it in one column
 *   reasonable.
 * ============================================================================
 */

import {
  PIXEL_ASSET_VERSION,
  type PixelAsset,
  type PixelPalette,
} from "./types";

/** The creation format's own version, separate from the asset contract's. */
export const PIXEL_CREATION_VERSION = 1;

/**
 * The logical resolutions a creation may use.
 *
 * The **same four** the density presets offer, so a creation is authored at a
 * resolution the engine has been measured and tested at, and so a scholar's
 * density preference and their drawing agree by construction.
 */
export const CREATION_ALLOWED_SIZES = [32, 40, 48, 64] as const;
export type CreationSize = (typeof CREATION_ALLOWED_SIZES)[number];

/**
 * Hard bounds.
 *
 * Every one of these is enforced before decode and again on validate. They exist
 * because a creation is stored, served, rendered in a loop on a production
 * surface, and written by a client that could be anything.
 */
export const MAX_CREATION_FRAMES = 16;
export const MAX_CREATION_COLORS = 16;
export const MIN_FRAME_MS = 60;
export const MAX_FRAME_MS = 2000;
export const MAX_TOTAL_MS = 30_000;
/**
 * The stored-size bound.
 *
 * Measured, not guessed: the largest legitimate creation — 64 × 64 at the
 * sixteen-frame ceiling, written as JSON — is about 70 KB, so the bound sits just
 * above it. It exists so a malformed or hostile payload cannot ask a database row
 * or a client response to carry something unbounded, not to constrain a scholar
 * who is drawing normally.
 */
export const MAX_PAYLOAD_BYTES = 128 * 1024;

/** One palette entry. `null` means "not a colour", which is never stored. */
export interface CreationColor {
  /** `#rrggbb`, lowercase, no alpha. Alpha would be a second drawing model. */
  readonly hex: string;
}

/**
 * A frame.
 *
 * `rows` are exactly `grid × grid` digits, top to bottom. Digit `n` indexes
 * `palette[n]`; `.` is transparent. There is no other encoding, because there
 * does not need to be one and a second encoding would be a second thing to
 * validate.
 */
export interface CreationFrame {
  readonly rows: readonly string[];
  /** How long this frame is held, in milliseconds. */
  readonly durationMs: number;
}

export type CreationPlayback = "once" | "loop";

export interface PixelCreation {
  readonly version: number;
  /** `user:<slug>`. The `user:` namespace keeps user content distinguishable. */
  readonly id: string;
  readonly name: string;
  /** Square, and one of `CREATION_ALLOWED_SIZES`. */
  readonly grid: number;
  /** Indices 0..15 use single hexadecimal digits; all sixteen colors are drawable. */
  readonly palette: readonly string[];
  readonly frames: readonly CreationFrame[];
  readonly playback: CreationPlayback;
}

// ─── Encoding ────────────────────────────────────────────────────────────────

/** The digits a frame may use, in index order. */
export const PALETTE_DIGITS = "0123456789abcdef";

/** One cell of a decoded frame: a palette index, or `null` for transparent. */
export type CellValue = number | null;

/**
 * Decodes a frame into cells.
 *
 * **Total.** Every row, every character, including rows of the wrong length and
 * characters that are not digits, produces a value rather than an exception.
 * Out-of-range indices decode to transparent instead of pointing past the palette
 * — the safe direction, because a wrong colour is a bug and a crash is an outage.
 */
export function decodeFrame(
  frame: { rows: readonly string[] },
  grid: number,
  paletteLength: number,
): CellValue[][] {
  const cells: CellValue[][] = [];
  for (let y = 0; y < grid; y += 1) {
    const row = frame.rows[y] ?? "";
    const line: CellValue[] = [];
    for (let x = 0; x < grid; x += 1) {
      const character = row[x] ?? ".";
      const index = PALETTE_DIGITS.indexOf(character);
      line.push(index >= 0 && index < paletteLength ? index : null);
    }
    cells.push(line);
  }
  return cells;
}

/** Encodes cells back into rows. The inverse of `decodeFrame`. */
export function encodeFrame(
  cells: readonly (readonly CellValue[])[],
  grid: number,
): string[] {
  const rows: string[] = [];
  for (let y = 0; y < grid; y += 1) {
    let row = "";
    for (let x = 0; x < grid; x += 1) {
      const value = cells[y]?.[x];
      row +=
        value === null || value === undefined || !Number.isInteger(value) || value < 0 || value >= PALETTE_DIGITS.length
          ? "."
          : PALETTE_DIGITS[value];
    }
    rows.push(row);
  }
  return rows;
}

/** An empty frame. */
export function emptyFrame(grid: number, durationMs = 240): CreationFrame {
  return {
    rows: Array.from({ length: grid }, () => ".".repeat(grid)),
    durationMs,
  };
}

// ─── Validation ──────────────────────────────────────────────────────────────

export type CreationIssueCode =
  | "not-an-object"
  | "version-unsupported"
  | "id-missing"
  | "id-malformed"
  | "name-missing"
  | "name-too-long"
  | "grid-unsupported"
  | "palette-too-large"
  | "palette-color-invalid"
  | "palette-color-duplicate"
  | "frames-empty"
  | "frames-too-many"
  | "frame-rows-mismatch"
  | "frame-row-width-mismatch"
  | "frame-index-out-of-palette"
  | "frame-duration-out-of-range"
  | "animation-too-long"
  | "playback-unknown"
  | "payload-too-large";

export interface CreationIssue {
  readonly code: CreationIssueCode;
  readonly path: string;
  readonly message: string;
}

const ID_PATTERN = /^user:[a-z0-9]+(?:-[a-z0-9]+)*$/;
const HEX_PATTERN = /^#[0-9a-f]{6}$/;

/**
 * Validates a creation. Returns every problem, in a stable order.
 *
 * Deliberately strict where the encoder is lenient: the encoder must not throw on
 * half-typed input, and the validator must not accept it. Between them, nothing
 * invalid reaches the display.
 */
export function validateCreation(input: unknown): CreationIssue[] {
  const issues: CreationIssue[] = [];
  const push = (code: CreationIssueCode, path: string, message: string) => {
    issues.push({ code, path, message });
  };

  if (typeof input !== "object" || input === null || Array.isArray(input)) {
    push("not-an-object", "", "A creation must be an object.");
    return issues;
  }

  const creation = input as Partial<PixelCreation>;

  if (creation.version !== PIXEL_CREATION_VERSION) {
    push(
      "version-unsupported",
      "version",
      `Creation declares version ${String(creation.version)}; this build understands ${PIXEL_CREATION_VERSION}.`,
    );
  }
  if (typeof creation.id !== "string" || !ID_PATTERN.test(creation.id)) {
    push(
      "id-malformed",
      "id",
      `Creation id must be "user:name" in lowercase kebab-case; got ${JSON.stringify(creation.id)}.`,
    );
  }
  if (typeof creation.name !== "string" || creation.name.trim().length === 0) {
    push("name-missing", "name", "A creation needs a name.");
  } else if (creation.name.length > 32) {
    push("name-too-long", "name", "A name may be at most 32 characters.");
  }

  // Bounds first, because everything below indexes by them.
  const grid = creation.grid;
  const gridOk =
    typeof grid === "number" &&
    (CREATION_ALLOWED_SIZES as readonly number[]).includes(grid);
  if (!gridOk) {
    push(
      "grid-unsupported",
      "grid",
      `Grid must be one of ${CREATION_ALLOWED_SIZES.join(", ")}; got ${String(grid)}.`,
    );
  }

  const palette = creation.palette;
  if (!Array.isArray(palette)) {
    push("palette-color-invalid", "palette", "A creation needs a palette.");
  } else {
    if (palette.length > MAX_CREATION_COLORS) {
      push(
        "palette-too-large",
        "palette",
        `${palette.length} colours exceeds the limit of ${MAX_CREATION_COLORS}.`,
      );
    }
    const seen = new Set<string>();
    for (let index = 0; index < palette.length; index += 1) {
      const colour = palette[index];
      if (typeof colour !== "string" || !HEX_PATTERN.test(colour)) {
        push(
          "palette-color-invalid",
          `palette[${index}]`,
          `Colours are lowercase #rrggbb; got ${JSON.stringify(colour)}.`,
        );
        continue;
      }
      if (seen.has(colour)) {
        push(
          "palette-color-duplicate",
          `palette[${index}]`,
          `${colour} appears more than once, which would make the drawing ambiguous.`,
        );
      }
      seen.add(colour);
    }
  }

  const paletteLength = Array.isArray(palette) ? palette.length : 0;
  const frames = creation.frames;
  if (!Array.isArray(frames) || frames.length === 0) {
    push("frames-empty", "frames", "A creation needs at least one frame.");
  } else {
    if (frames.length > MAX_CREATION_FRAMES) {
      push(
        "frames-too-many",
        "frames",
        `${frames.length} frames exceeds the limit of ${MAX_CREATION_FRAMES}.`,
      );
    }
    let total = 0;
    for (let index = 0; index < frames.length; index += 1) {
      const frame = frames[index];
      const path = `frames[${index}]`;
      if (typeof frame !== "object" || frame === null) {
        push("frame-rows-mismatch", path, "A frame must be an object.");
        continue;
      }
      if (!Array.isArray(frame.rows) || frame.rows.length !== grid) {
        push(
          "frame-rows-mismatch",
          `${path}.rows`,
          `A frame has one row per grid line: expected ${String(grid)}, got ${Array.isArray(frame.rows) ? frame.rows.length : "none"}.`,
        );
      } else {
        for (let row = 0; row < frame.rows.length; row += 1) {
          const line = frame.rows[row];
          if (typeof line !== "string" || line.length !== grid) {
            push(
              "frame-row-width-mismatch",
              `${path}.rows[${row}]`,
              `Every row is ${String(grid)} cells wide; row ${row} is ${typeof line === "string" ? line.length : "not a string"}.`,
            );
            continue;
          }
          // A digit the palette does not define is a real authoring mistake —
          // unlike the encoder, the validator refuses it rather than guessing.
          for (let column = 0; column < line.length; column += 1) {
            const character = line[column];
            const value = PALETTE_DIGITS.indexOf(character);
            if (value >= 0 && value >= paletteLength) {
              push(
                "frame-index-out-of-palette",
                `${path}.rows[${row}]`,
                `Row ${row}, column ${column} uses colour ${value}, but the palette has ${paletteLength}.`,
              );
            } else if (value < 0 && character !== ".") {
              push(
                "frame-row-width-mismatch",
                `${path}.rows[${row}]`,
                `Row ${row}, column ${column} is ${JSON.stringify(character)}; cells are a palette digit or ".".`,
              );
            }
          }
        }
      }

      const duration = frame.durationMs;
      if (
        typeof duration !== "number" ||
        !Number.isInteger(duration) ||
        duration < MIN_FRAME_MS ||
        duration > MAX_FRAME_MS
      ) {
        push(
          "frame-duration-out-of-range",
          `${path}.durationMs`,
          `Frame duration must be a whole number of milliseconds between ${MIN_FRAME_MS} and ${MAX_FRAME_MS}; got ${String(duration)}.`,
        );
      } else {
        total += duration;
      }
    }

    if (frames.length > 1 && total > MAX_TOTAL_MS) {
      push(
        "animation-too-long",
        "frames",
        `The animation runs for ${total}ms, over the ${MAX_TOTAL_MS}ms limit.`,
      );
    }
  }

  if (creation.playback !== "once" && creation.playback !== "loop") {
    push(
      "playback-unknown",
      "playback",
      `Playback must be "once" or "loop"; got ${JSON.stringify(creation.playback)}.`,
    );
  }

  // The stored size, not the decoded size: what a database row has to carry.
  const bytes = approximatePayloadBytes(input);
  if (bytes > MAX_PAYLOAD_BYTES) {
    push(
      "payload-too-large",
      "",
      `The creation is about ${Math.round(bytes / 1024)} KB, over the ${MAX_PAYLOAD_BYTES / 1024} KB limit.`,
    );
  }

  return issues;
}

/** Throws one readable error when a creation is invalid. */
export function assertValidCreation(input: unknown): PixelCreation {
  const issues = validateCreation(input);
  if (issues.length > 0) {
    throw new Error(
      `Pixel creation is invalid:\n${issues
        .map((issue) => `  - [${issue.code}] ${issue.path}: ${issue.message}`)
        .join("\n")}`,
    );
  }
  return input as PixelCreation;
}

/**
 * Roughly how many bytes a creation occupies when serialised.
 *
 * Measured on the stringified form rather than estimated from the frame count,
 * because the frames *are* the payload and an estimate that disagreed with the
 * database would be worse than no check.
 */
export function approximatePayloadBytes(input: unknown): number {
  try {
    return JSON.stringify(input).length;
  } catch {
    // A value that cannot be serialised is a value that cannot be stored.
    return Number.MAX_SAFE_INTEGER;
  }
}

/** Whether a value is a creation this build can draw. */
export function isDrawableCreation(input: unknown): input is PixelCreation {
  return validateCreation(input).length === 0;
}

/** Valid artwork with at least one authored opaque cell (blank drafts remain saveable). */
export function hasCreationPixels(value: unknown): value is PixelCreation {
  return validateCreation(value).length === 0 && (value as PixelCreation).frames.some(frame => frame.rows.some(row => /[0-9a-f]/.test(row)));
}

import { selectedCompanionsForUsers } from "./pixel-companion-service";
import { prisma } from "@/lib/prisma";
import { getRelationship, isVisible } from "@/lib/privacy";
import { Relationship } from "@/lib/privacy-types";
import { isUserBlocked } from "@/lib/block-service";
import { TimezoneService } from "@/lib/timezone-service";
import { unstable_cache } from "next/cache";
import { getLevelProgress, calculateRequiredXp } from "@/lib/game-engine";
import { cachedWithRedis } from "@/lib/redis";

export interface ProfileDossierResult {
  profile: any | null;
  relationship: string;
  isSelf: boolean;
  permissions: {
    canSendFriendRequest: boolean;
    canSendMessage: boolean;
    canRemoveFriend?: boolean;
    canBlock?: boolean;
    canUnblock?: boolean;
  } | null;
  privacySettings?: {
    isProfileVisible: boolean;
    showRank: boolean;
    showStudyHours: boolean;
    showAchievements: boolean;
  };
  error?: string | null;
  status: number;
}

async function fetchTargetUserData(normalized: string) {
  // Redis (or in-process fallback) absorbs repeated profile reads across
  // serverless instances — a 60s TTL keeps dossiers fresh without hammering
  // Postgres on every profile view.
  return cachedWithRedis(`user-data:${normalized}`, 60, () =>
    prisma.user.findUnique({
      where: { username: normalized },
    select: {
      id: true,
      username: true,
      name: true,
      scholarId: true,
      verificationStatus: true,
      avatarUrl: true,
      bannerUrl: true,
      bio: true,
      hunterRank: true,
      level: true,
      currentXP: true,
      xpToNextLevel: true,
      hp: true,
      maxHp: true,
      streakDays: true,
      totalStudyMinutes: true,
      totalStudySeconds: true,
      timezone: true,
      lastActiveDate: true,
      lastSeenAt: true,
      activeAvatar: true,
      activeFrame: true,
      activeTitle: true,
      activeAura: true,
      activeNameColor: true,
      characterConfig: true,
      statEndurance: true,
      statTenacity: true,
      statVelocity: true,
      statSynthesis: true,
      statDiscipline: true,
      createdAt: true,
      stats: {
        select: {
          level: true,
          xp: true,
          rank: true,
          currency: true,
          skillPoints: true,
          endurance: true,
          tenacity: true,
          velocity: true,
          discipline: true,
          synthesis: true,
        },
      },
      inventory: {
        where: { isEquipped: true },
        select: {
          id: true,
          itemId: true,
          isEquipped: true,
          item: {
            select: {
              sku: true,
              name: true,
              slot: true,
              rarity: true,
              spriteLayer: true,
              setKey: true,
            },
          },
        },
      },
      privacy: {
        select: {
          profileVisibility: true,
          showOnlineStatus: true,
          showCurrentSession: true,
          showStudyHours: true,
          showRank: true,
          showAchievements: true,
          allowFriendRequests: true,
          allowDirectMessages: true,
        },
      },
      connectedAccounts: {
        select: {
          provider: true,
          providerUsername: true,
        },
      },
      achievements: {
        take: 50,
        orderBy: { claimedAt: "desc" },
        select: {
          achievementId: true,
          claimedAt: true,
        },
      },
    },
  })
  );
}

/**
 * Cached loader for target user profile base data
 */
export async function getCachedUserData(username: string) {
  const normalized = username.toLowerCase();
  try {
    const cachedFn = unstable_cache(
      async () => fetchTargetUserData(normalized),
      [`user-${normalized}`, `profile-stats-${normalized}`],
      {
        revalidate: 3600,
        tags: [`user-${normalized}`, `profile-stats-${normalized}`],
      }
    );
    return await cachedFn();
  } catch {
    // Graceful fallback for non-static / test environments where incrementalCache is not initialized
    return await fetchTargetUserData(normalized);
  }
}

/**
 * Server-side profile dossier data loader with strict column projections
 * and ISO string date serialization across Server/Client boundary.
 */
export async function getProfileDossier(
  username: string,
  viewerId: number | null
): Promise<ProfileDossierResult> {
  const targetUser = await getCachedUserData(username);

  if (!targetUser) {
    return {
      profile: null,
      relationship: "PUBLIC",
      isSelf: false,
      permissions: null,
      error: "Scholar not found in the system registry.",
      status: 404,
    };
  }

  const isSelf = viewerId === targetUser.id;

  // ── Relationship + block state resolved in ONE parallel hop ──
  const [baseRelationship, isBlockedByViewer, isBlockedByTarget] = await Promise.all([
    getRelationship(viewerId, targetUser.id),
    viewerId && !isSelf ? isUserBlocked(viewerId, targetUser.id) : Promise.resolve(false),
    viewerId && !isSelf ? isUserBlocked(targetUser.id, viewerId) : Promise.resolve(false),
  ]);

  let relationshipStatus: string = baseRelationship;
  if (isBlockedByViewer) {
    relationshipStatus = "BLOCKED";
  } else if (!isSelf && baseRelationship === Relationship.PUBLIC && viewerId) {
    // Pending request checks only matter for PUBLIC relationships — one parallel hop.
    const [pendingSent, pendingReceived] = await Promise.all([
      prisma.friendRequest.findUnique({
        where: {
          senderId_receiverId: {
            senderId: viewerId,
            receiverId: targetUser.id,
          },
        },
      }).catch(() => null),
      prisma.friendRequest.findUnique({
        where: {
          senderId_receiverId: {
            senderId: targetUser.id,
            receiverId: viewerId,
          },
        },
      }).catch(() => null),
    ]);
    if (pendingSent && pendingSent.status === "PENDING") {
      relationshipStatus = "PENDING_SENT";
    } else if (pendingReceived && pendingReceived.status === "PENDING") {
      relationshipStatus = "PENDING_RECEIVED";
    }
  }

  const privacy = targetUser.privacy || {
    profileVisibility: "PUBLIC",
    showOnlineStatus: "PUBLIC",
    showCurrentSession: "PUBLIC",
    showStudyHours: "PUBLIC",
    showRank: "PUBLIC",
    showAchievements: "PUBLIC",
    allowFriendRequests: "PUBLIC",
    allowDirectMessages: "FRIENDS",
  };

  // ── Aggregate stats in one parallel hop ──
  const targetTimezone = targetUser.timezone || "UTC";
  const todayStart = TimezoneService.getStartOfDayUTC(targetTimezone);

  const [completedQuestsCount, todaySessions] = await Promise.all([
    prisma.quest.count({
      where: { userId: targetUser.id, status: "COMPLETED" },
    }).catch(() => 0),
    prisma.studySession?.findMany
      ? prisma.studySession.findMany({
          where: {
            userId: targetUser.id,
            startedAt: { gte: todayStart },
          },
          select: {
            durationMinutes: true,
            durationSeconds: true,
            startedAt: true,
            endedAt: true,
          },
        }).catch(() => [])
      : Promise.resolve([]),
  ]);

  let completedTodaySeconds = 0;
  let todayStudySeconds = 0;
  let activeSessionStartedAt: string | null = null;
  const now = new Date();

  for (const s of todaySessions) {
    if (!s.endedAt) {
      // Active (unended) session: count its already-flushed stored seconds.
      // Live = freshly started (≤3 min) OR has flushed progress and is not a
      // zombie (>12h). Stale 0-second rows are ignored.
      const started = new Date(s.startedAt);
      const elapsed = Math.floor((now.getTime() - started.getTime()) / 1000);
      const stored = (s.durationSeconds || (s.durationMinutes * 60) || 0);
      const isLive =
        (elapsed >= 0 && elapsed <= 180) ||
        (stored > 0 && elapsed > 0 && elapsed <= 12 * 3600);
      if (isLive) {
        todayStudySeconds += stored;
        if (!activeSessionStartedAt) {
          activeSessionStartedAt = s.startedAt ? new Date(s.startedAt).toISOString() : null;
        }
      }
    } else {
      const sec = (s.durationSeconds || (s.durationMinutes * 60) || 0);
      completedTodaySeconds += sec;
      todayStudySeconds += sec;
    }
  }
  const todayStudyMinutes = Math.floor(todayStudySeconds / 60);
  const isStudying = Boolean(activeSessionStartedAt);

  const ghAcc = targetUser.connectedAccounts?.find((c) => c.provider === "GITHUB");
  const discordAcc = targetUser.connectedAccounts?.find((c) => c.provider === "DISCORD");
  const igAcc = targetUser.connectedAccounts?.find((c) => c.provider === "INSTAGRAM");

  const connectedSocials: Record<string, string> = {};
  if (ghAcc?.providerUsername) connectedSocials.github = ghAcc.providerUsername;
  if (discordAcc?.providerUsername) connectedSocials.discord = discordAcc.providerUsername;
  if (igAcc?.providerUsername) connectedSocials.instagram = igAcc.providerUsername;

    const userStats = targetUser.stats || {
      level: targetUser.level || 1,
      xp: targetUser.currentXP || 0,
      rank: targetUser.hunterRank || "RANK E",
      currency: 0,
      skillPoints: 0,
      endurance: targetUser.statEndurance ?? 10,
      tenacity: targetUser.statTenacity ?? 10,
      velocity: targetUser.statVelocity ?? 10,
      discipline: targetUser.statDiscipline ?? 10,
      synthesis: targetUser.statSynthesis ?? 10,
    };

    // XP PROGRESSION (canonical, level-correct):
    // `getLevelProgress` needs the LIFETIME cumulative XP. If the canonical
    // UserStats row exists, it holds the lifetime total; otherwise we rebuilt
    // `userStats.xp` from `User.currentXP` (which is XP INTO the current
    // level) — so reconstruct the lifetime total before computing progress.
    //
    // The dashboard reads `User.currentXP` / `User.xpToNextLevel` directly,
    // and both are into-level / per-level-bucket values maintained by the
    // canonical progression RPC. We used to override `currentXP` with the
    // LIFETIME cumulative number while leaving the per-level bucket, which
    // produced "7412 / 627 XP" on a friend's level-17 card — the lifetime
    // total divided by a single level's bucket. Now the numerator is the
    // exact XP INTO the friend's current level and the denominator is the
    // total XP required to clear THAT level (either matches perfectly).
    const statLevel = userStats.level || targetUser.level || 1;
    const lifetimeXp = targetUser.stats
      ? userStats.xp
      : calculateRequiredXp(statLevel) + (targetUser.currentXP || 0);

    const levelProgress = getLevelProgress(lifetimeXp, statLevel);

    // Online status — mirrors the friends roster: online only if this user's
    // heartbeat (`lastSeenAt`, refreshed ~every 60s while the app is open) is
    // fresh within 2 minutes. Older than that → offline (the card must never
    // show a green dot for someone who walked away).
    const isOnline =
      !!targetUser.lastSeenAt &&
      Date.now() - new Date(targetUser.lastSeenAt).getTime() <= 2 * 60 * 1000;

    const rawProfileData = {
      id: targetUser.id,
      name: targetUser.name,
      username: targetUser.username,
      scholarId: (targetUser as any).scholarId,
      verificationStatus: (targetUser as any).verificationStatus,
      avatarUrl: targetUser.avatarUrl,
      bannerUrl: targetUser.bannerUrl,
      bio: targetUser.bio,
      hunterRank: userStats.rank || targetUser.hunterRank,
      level: statLevel,
      currentXP: levelProgress.xpIntoCurrentLevel,
      xpToNextLevel: levelProgress.xpForCurrentBracket,
      levelProgress: levelProgress.progressPercentage,
      hp: targetUser.hp,
      maxHp: targetUser.maxHp,
      streakDays: targetUser.streakDays,
      totalStudyMinutes: targetUser.totalStudyMinutes,
      totalStudySeconds: targetUser.totalStudySeconds || (targetUser.totalStudyMinutes * 60),
      todayStudyMinutes,
      todayStudySeconds,
      completedTodaySeconds,
      isStudying,
      isOnline,
      activeSessionStartedAt,
      activeAvatar: targetUser.activeAvatar,
      activeFrame: targetUser.activeFrame,
      activeTitle: targetUser.activeTitle,
      activeAura: targetUser.activeAura,
      activeNameColor: targetUser.activeNameColor,
      characterConfig: targetUser.characterConfig || null,
      socialLinks: connectedSocials,
      connectedAccounts: {
        github: ghAcc?.providerUsername || null,
        discord: discordAcc?.providerUsername || null,
        instagram: igAcc?.providerUsername || null,
      },
      stats: {
        endurance: userStats.endurance ?? targetUser.statEndurance ?? 10,
        tenacity: userStats.tenacity ?? targetUser.statTenacity ?? 10,
        velocity: userStats.velocity ?? targetUser.statVelocity ?? 10,
        discipline: userStats.discipline ?? targetUser.statDiscipline ?? 10,
        synthesis: userStats.synthesis ?? targetUser.statSynthesis ?? 10,
      },
      userStats,
      inventory: (targetUser.inventory || []).map((inv: any) => ({
        id: inv.id,
        itemId: inv.itemId,
        isEquipped: inv.isEquipped,
        item: inv.item,
      })),
      completedQuestsCount,
      achievementsCount: targetUser.achievements?.length || 0,
      recentAchievements: (targetUser.achievements || []).map((a: any) => ({
        achievementId: a.achievementId,
        claimedAt: a.claimedAt ? (typeof a.claimedAt === "string" ? a.claimedAt : new Date(a.claimedAt).toISOString()) : new Date().toISOString(),
      })),
      lastActiveDate: targetUser.lastActiveDate,
      createdAt: targetUser.createdAt ? (typeof targetUser.createdAt === "string" ? targetUser.createdAt : new Date(targetUser.createdAt).toISOString()) : new Date().toISOString(),
    };

    const isRestrictedByBlock = isBlockedByViewer || isBlockedByTarget;
    const isProfilePublic = isVisible(privacy.profileVisibility, baseRelationship);

    let finalProfile: any = null;
    if (isRestrictedByBlock || (!isSelf && !isProfilePublic)) {
      finalProfile = {
        id: targetUser.id,
        username: targetUser.username,
        name: targetUser.name,
        avatarUrl: targetUser.avatarUrl,
        activeAvatar: targetUser.activeAvatar,
        activeFrame: targetUser.activeFrame,
        activeTitle: targetUser.activeTitle,
        characterConfig: undefined,
        isRestricted: true,
        bio: undefined,
        stats: undefined,
        inventory: undefined,
        socialLinks: undefined,
        connectedAccounts: undefined,
        recentAchievements: undefined,
        achievementsCount: undefined,
      };
    } else {
      const showStudy = isSelf || isVisible(privacy.showStudyHours, baseRelationship);
      const showRank = isSelf || isVisible(privacy.showRank, baseRelationship);
      const showAchievements = isSelf || isVisible(privacy.showAchievements, baseRelationship);
      const showOnline = isSelf || isVisible(privacy.showOnlineStatus, baseRelationship);

      const companions = await selectedCompanionsForUsers([targetUser.id], viewerId, baseRelationship === Relationship.FRIEND || isSelf ? "friends" : "public", false);
      finalProfile = {
        ...rawProfileData,
        companion: companions.get(targetUser.id),
        hunterRank: showRank ? rawProfileData.hunterRank : undefined,
        level: showRank ? rawProfileData.level : undefined,
        currentXP: showRank ? rawProfileData.currentXP : undefined,
        xpToNextLevel: showRank ? rawProfileData.xpToNextLevel : undefined,
        levelProgress: showRank ? rawProfileData.levelProgress : undefined,
        totalStudyMinutes: showStudy ? rawProfileData.totalStudyMinutes : undefined,
        totalStudySeconds: showStudy ? rawProfileData.totalStudySeconds : undefined,
        todayStudyMinutes: showStudy ? rawProfileData.todayStudyMinutes : undefined,
        todayStudySeconds: showStudy ? rawProfileData.todayStudySeconds : undefined,
        completedTodaySeconds: showStudy ? rawProfileData.completedTodaySeconds : undefined,
        streakDays: showStudy ? rawProfileData.streakDays : undefined,
        stats: showStudy ? rawProfileData.stats : undefined,
        inventory: rawProfileData.inventory,
        recentAchievements: showAchievements ? rawProfileData.recentAchievements : undefined,
        achievementsCount: showAchievements ? rawProfileData.achievementsCount : undefined,
        lastActiveDate: showOnline ? rawProfileData.lastActiveDate : undefined,
        isOnline: showOnline ? rawProfileData.isOnline : undefined,
      };
    }

  const permissions = {
    canSendFriendRequest: !isSelf && !isRestrictedByBlock && isVisible(privacy.allowFriendRequests, baseRelationship) && relationshipStatus === Relationship.PUBLIC,
    canSendMessage: !isSelf && !isRestrictedByBlock && isVisible(privacy.allowDirectMessages, baseRelationship),
    canRemoveFriend: baseRelationship === Relationship.FRIEND,
    canBlock: !isSelf && !isBlockedByViewer,
    canUnblock: !isSelf && isBlockedByViewer,
  };

  const privacySettings = {
    isProfileVisible: isProfilePublic,
    showRank: isSelf || isVisible(privacy.showRank, baseRelationship),
    showStudyHours: isSelf || isVisible(privacy.showStudyHours, baseRelationship),
    showAchievements: isSelf || isVisible(privacy.showAchievements, baseRelationship),
  };

  return {
    profile: finalProfile,
    relationship: relationshipStatus,
    isSelf,
    permissions,
    privacySettings,
    error: null,
    status: 200,
  };
}
